			obj.setR1_TYPE_OF_ACCOUNT_NOSTRO1(rs.getString("R1_TYPE_OF_ACCOUNT_NOSTRO1"));
			obj.setR1_PURPOSE_NOSTRO1(rs.getString("R1_PURPOSE_NOSTRO1"));
			obj.setR1_CURRENCY_NOSTRO1(rs.getString("R1_CURRENCY_NOSTRO1"));
