	private void insertResubP1Summary(BrrsMNosvosP1ResbuSummaryEntity entity) {
		try {
			StringBuilder columns = new StringBuilder(
					"INSERT INTO BRRS_M_NOSVOS_P1_RESUB_SUMMARY (REPORT_DATE,REPORT_VERSION,REPORT_RESUB_DATE,");

			StringBuilder values = new StringBuilder(" VALUES (?,?,?,");

			List<Object> params = new ArrayList<>();

			params.add(entity.getREPORT_DATE());
			params.add(entity.getREPORT_VERSION());
			params.add(entity.getREPORT_RESUB_DATE());

			String[] p1Fields = { "NAME_OF_BANK_AND_COUNTRY_NOSTRO", "TYPE_OF_ACCOUNT_NOSTRO", "PURPOSE_NOSTRO",
					"CURRENCY_NOSTRO", "SOVEREIGN_RATING_AAA_AA_A1_NOSTRO", "RISK_WEIGHT_NOSTRO",
					"AMOUNT_DEMAND_NOSTRO", "AMOUNT_TIME_NOSTRO", "RISK_WEIGHTED_AMOUNT_NOSTRO" };

			for (int i = 1; i <= 101; i++) {
				for (String field : p1Fields) {
					columns.append("R").append(i).append("_").append(field).append(",");
					values.append("?,");
					params.add(getValue(entity, "getR" + i + "_" + field));
				}
			}

			String[] totalFields = { "TOTAL_AMOUNT_DEMAND_NOSTRO", "TOTAL_AMOUNT_TIME_NOSTRO",
					"TOTAL_RISK_WEIGHTED_AMOUNT_NOSTRO" };
			for (String field : totalFields) {
				columns.append("R101_").append(field).append(",");
				values.append("?,");
				params.add(getValue(entity, "getR101_" + field));
			}

			columns.append("REPORT_FREQUENCY,REPORT_CODE,REPORT_DESC,ENTITY_FLG,MODIFY_FLG,DEL_FLG");
			values.append("?,?,?,?,?,?");
			params.add(entity.getREPORT_FREQUENCY());
			params.add(entity.getREPORT_CODE());
			params.add(entity.getREPORT_DESC());
			params.add(entity.getENTITY_FLG());
			params.add(entity.getMODIFY_FLG());
			params.add(entity.getDEL_FLG());

			columns.append(")");
			values.append(")");

			jdbcTemplate.update(columns.toString() + values.toString(), params.toArray());

		} catch (Exception e) {
			e.printStackTrace();
			throw new RuntimeException("Error inserting RESUB P1 SUMMARY", e);
		}
	}

