	/**
	 * Get all archival data for all parts (P1-P5) Used for dropdown/selection lists
	 */
	public List<Object[]> getM_NOSVOSArchival() {
		List<Object[]> archivalList = new ArrayList<>();

		try {
			// P1 Archival
			archivalList.addAll(p1Archival_getArchivalList());

			// P2 Archival
			archivalList.addAll(p2Archival_getArchivalList());

			// P3 Archival
			archivalList.addAll(p3Archival_getArchivalList());

			// P4 Archival
			archivalList.addAll(p4Archival_getArchivalList());

			// P5 Archival - ADDED (was missing)
			archivalList.addAll(p5Archival_getArchivalList());

			logger.info("Total Archival Records: {}", archivalList.size());

		} catch (Exception e) {
			logger.error("Error fetching M_NOSVOS Archival data", e);
		}

		return archivalList;
	}

	/**
	 * Get latest archival entries for dropdown Fixed: Now includes all parts P1-P5
	 */
	public List<Object[]> getM_NOSVOSArchivalFirstList() {
		List<Object[]> archivalList = new ArrayList<>();

		try {
			// P1 Latest
			List<BrrsMNosvosP1Archival> p1List = p1Archival_getdatabydateListWithVersion();
			for (BrrsMNosvosP1Archival entity : p1List) {
				archivalList.add(new Object[] { entity.getREPORT_DATE(), entity.getREPORT_VERSION(),
						entity.getREPORT_RESUB_DATE() });
			}

			// P2 Latest
			List<BrrsMNosvosP2Archival> p2List = p2Archival_getdatabydateListWithVersion();
			for (BrrsMNosvosP2Archival entity : p2List) {
				archivalList.add(new Object[] { entity.getREPORT_DATE(), entity.getREPORT_VERSION(),
						entity.getREPORT_RESUB_DATE() });
			}

			// P3 Latest
			List<BrrsMNosvosP3Archival> p3List = p3Archival_getdatabydateListWithVersion();
			for (BrrsMNosvosP3Archival entity : p3List) {
				archivalList.add(new Object[] { entity.getREPORT_DATE(), entity.getREPORT_VERSION(),
						entity.getREPORT_RESUB_DATE() });
			}

			// P4 Latest
			List<BrrsMNosvosP4Archival> p4List = p4Archival_getdatabydateListWithVersion();
			for (BrrsMNosvosP4Archival entity : p4List) {
				archivalList.add(new Object[] { entity.getREPORT_DATE(), entity.getREPORT_VERSION(),
						entity.getREPORT_RESUB_DATE() });
			}

			// P5 Latest
			List<BrrsMNosvosP5Archival> p5List = p5Archival_getdatabydateListWithVersion();
			for (BrrsMNosvosP5Archival entity : p5List) {
				archivalList.add(new Object[] { entity.getREPORT_DATE(), entity.getREPORT_VERSION(),
						entity.getREPORT_RESUB_DATE() });
			}

			logger.info("Fetched {} archival record(s)", archivalList.size());

		} catch (Exception e) {
			logger.error("Error fetching M_NOSVOS Archival First List", e);
		}

		return archivalList;
	}

	// ================================================================
	// ======================== MAIN EXCEL ENTRY =======================
	// ================================================================

	public byte[] getM_NOSVOSExcel(String filename, String reportId, String fromdate, String todate, String currency,
			String dtltype, String type, String format, BigDecimal version) throws Exception {

		logger.info("Service: Starting NOSVOS Excel generation process.");
		logger.info("Type: {}, Version: {}, Format: {}, Date: {}", type, version, format, todate);

		// ============================================================
		// ROUTE BASED ON TYPE (EXACTLY LIKE LA2)
		// ============================================================

		// ARCHIVAL
		if ("ARCHIVAL".equalsIgnoreCase(type) && version != null) {
			logger.info("Routing to ARCHIVAL Excel generation");
			return getExcelM_NOSVOSARCHIVAL(filename, reportId, fromdate, todate, currency, dtltype, type, version);
		}

		// RESUB
		if ("RESUB".equalsIgnoreCase(type) && version != null) {
			logger.info("Routing to RESUB Excel generation");
			return getExcelM_NOSVOSRESUB(filename, reportId, fromdate, todate, currency, dtltype, type, version);
		}

		// ============================================================
		// NORMAL FLOW
		// ============================================================
		logger.info("Service: Generating NORMAL NOSVOS Excel");

		Date reportDate = dateformat.parse(todate);

		// Fetch data for all 5 parts (FIXED: Added P5)
		List<BrrsMNosvosP1> dataList = p1_getDataByDate(reportDate);
		List<BrrsMNosvosP2> dataList2 = p2_getDataByDate(reportDate);
		List<BrrsMNosvosP3> dataList3 = p3_getDataByDate(reportDate);
		List<BrrsMNosvosP4> dataList4 = p4_getDataByDate(reportDate);
		List<BrrsMNosvosP5> dataList5 = p5_getDataByDate(reportDate); // FIXED: Added P5

		// Check if any data exists (P1 is mandatory)
		if (dataList.isEmpty()) {
			logger.warn("Service: No data found for NOSVOS report. Returning empty result.");
			return new byte[0];
		}

		// Log data sizes (FIXED: Replaced System.out with logger)
		logger.info("Data sizes - P1: {}, P2: {}, P3: {}, P4: {}, P5: {}", dataList.size(), dataList2.size(),
				dataList3.size(), dataList4.size(), dataList5.size());

		// ============================================================
		// LOAD TEMPLATE (EXACTLY LIKE LA2)
		// ============================================================
		String templateDir = env.getProperty("output.exportpathtemp");
		Path templatePath = Paths.get(templateDir, filename);

		logger.info("Service: Attempting to load template from path: {}", templatePath.toAbsolutePath());

		if (!Files.exists(templatePath)) {
			throw new FileNotFoundException("Template file not found at: " + templatePath.toAbsolutePath());
		}
		if (!Files.isReadable(templatePath)) {
			throw new SecurityException("Template file exists but is not readable: " + templatePath.toAbsolutePath());
		}

		// ============================================================
		// GENERATE EXCEL (EXACTLY LIKE LA2)
		// ============================================================
		try (InputStream templateInputStream = Files.newInputStream(templatePath);
				Workbook workbook = WorkbookFactory.create(templateInputStream);
				ByteArrayOutputStream out = new ByteArrayOutputStream()) {

			Sheet sheet = workbook.getSheetAt(0);

			// --- Style Definitions (EXACTLY LIKE LA2) ---
			CreationHelper createHelper = workbook.getCreationHelper();

			CellStyle dateStyle = workbook.createCellStyle();
			dateStyle.setDataFormat(createHelper.createDataFormat().getFormat("dd-MM-yyyy"));
			dateStyle.setBorderBottom(BorderStyle.THIN);
			dateStyle.setBorderTop(BorderStyle.THIN);
			dateStyle.setBorderLeft(BorderStyle.THIN);
			dateStyle.setBorderRight(BorderStyle.THIN);

			CellStyle textStyle = workbook.createCellStyle();
			textStyle.setBorderBottom(BorderStyle.THIN);
			textStyle.setBorderTop(BorderStyle.THIN);
			textStyle.setBorderLeft(BorderStyle.THIN);
			textStyle.setBorderRight(BorderStyle.THIN);

			// Create the font (EXACTLY LIKE LA2)
			Font font = workbook.createFont();
			font.setFontHeightInPoints((short) 8);
			font.setFontName("Arial");

			CellStyle numberStyle = workbook.createCellStyle();
			numberStyle.setBorderBottom(BorderStyle.THIN);
			numberStyle.setBorderTop(BorderStyle.THIN);
			numberStyle.setBorderLeft(BorderStyle.THIN);
			numberStyle.setBorderRight(BorderStyle.THIN);
			numberStyle.setFont(font);
			// --- End of Style Definitions ---

			// =========================================================
			// SET REPORT DATE - ROW 6 / COLUMN B (EXACTLY LIKE LA2)
			// =========================================================
			Row row = sheet.getRow(5);
			if (row == null) {
				row = sheet.createRow(5);
			}

			Cell cell = row.getCell(1); // FIXED: Column B is index 1, not 2
			if (cell == null) {
				cell = row.createCell(1);
			}

			if (reportDate != null) {
				cell.setCellValue(reportDate);
				cell.setCellStyle(dateStyle);
			} else {
				cell.setCellValue("");
				cell.setCellStyle(textStyle);
			}

			// =========================================================
			// CHECK FOR EMAIL FORMAT
			// =========================================================
			boolean isEmail = "email".equalsIgnoreCase(format);

			// =========================================================
			// POPULATE DATA (USING HELPER METHODS)
			// =========================================================
			if (isEmail) {
				// Email format - uses different row/column mapping
				populateEmailP1(sheet, dataList, numberStyle, textStyle);
				populateEmailP2(sheet, dataList2, numberStyle, textStyle);
				populateEmailP3(sheet, dataList3, numberStyle, textStyle);
				populateEmailP4(sheet, dataList4, numberStyle, textStyle);
				populateEmailP5(sheet, dataList5, numberStyle, textStyle);
			} else {
				// Normal format
				populateP1(sheet, dataList, numberStyle, textStyle);
				populateP2(sheet, dataList2, numberStyle, textStyle);
				populateP3(sheet, dataList3, numberStyle, textStyle);
				populateP4(sheet, dataList4, numberStyle, textStyle);
				populateP5(sheet, dataList5, numberStyle, textStyle);
			}

			// =========================================================
			// FINALIZE EXCEL (EXACTLY LIKE LA2)
			// =========================================================
			workbook.getCreationHelper().createFormulaEvaluator().evaluateAll();
			workbook.write(out);

			logger.info("Service: Excel data successfully written to memory buffer ({} bytes).", out.size());

			// Audit log (EXACTLY LIKE LA2)
			ServletRequestAttributes attrs = (ServletRequestAttributes) RequestContextHolder.getRequestAttributes();
			if (attrs != null) {
				HttpServletRequest request = attrs.getRequest();
				String userid = (String) request.getSession().getAttribute("USERID");
				auditService.createBusinessAudit(userid, "DOWNLOAD", "M_NOSVOS SUMMARY", null,
						"BRRS_M_NOSVOS_SUMMARYTABLE");
			}

			return out.toByteArray();
		}
	}

