	// ================================================================
	// ======================== HELPER METHODS =========================
	// ================================================================

	/**
	 * Helper method to set String cell value (EXACTLY LIKE LA2)
	 */
	private void setStringCellValue(Cell cell, Object record, String methodName, CellStyle textStyle) {
		try {
			Method method = record.getClass().getMethod(methodName);
			String value = (String) method.invoke(record);
			if (value != null && !value.isEmpty()) {
				cell.setCellValue(value.trim());
				cell.setCellStyle(textStyle);
			} else {
				cell.setCellValue("");
				cell.setCellStyle(textStyle);
			}
		} catch (Exception e) {
			cell.setCellValue("");
			cell.setCellStyle(textStyle);
		}
	}

	/**
	 * Helper method to set BigDecimal cell value (EXACTLY LIKE LA2)
	 */
	private void setBigDecimalCellValue(Cell cell, Object record, String methodName, CellStyle numberStyle,
			CellStyle textStyle) {
		try {
			Method method = record.getClass().getMethod(methodName);
			BigDecimal value = (BigDecimal) method.invoke(record);
			if (value != null) {
				cell.setCellValue(value.doubleValue());
				cell.setCellStyle(numberStyle);
			} else {
				cell.setCellValue("");
				cell.setCellStyle(textStyle);
			}
		} catch (Exception e) {
			cell.setCellValue("");
			cell.setCellStyle(textStyle);
		}
	}

