	// ================================================================

	private void writeEmailResubExcelRowData1(Sheet sheet, List<BrrsMNosvosP1ResbuSummaryEntity> dataList,
			String[] rowCodes, String[] fieldSuffixes, int baseRow, CellStyle numberStyle, CellStyle textStyle) {

		logger.info("Writing Email Resub P1 Row Data");

		if (dataList == null || dataList.isEmpty()) {
			logger.warn("No data available for P1 Email Resub");
			return;
		}

		BrrsMNosvosP1ResbuSummaryEntity record = dataList.get(0);

		// =========================================================
		// SET REPORT DATE - ROW 6 / COLUMN B (Index 1)
		// =========================================================
		Row reportRow = sheet.getRow(5);
		if (reportRow == null) {
			reportRow = sheet.createRow(5);
		}

		Cell reportDateCell = reportRow.getCell(1);
		if (reportDateCell == null) {
			reportDateCell = reportRow.createCell(1);
		}

		if (record.getREPORT_DATE() != null) {
			reportDateCell.setCellValue(record.getREPORT_DATE());
			reportDateCell.setCellStyle(textStyle);
		} else {
			reportDateCell.setCellValue("");
			reportDateCell.setCellStyle(textStyle);
		}

		// =========================================================
		// P1 fields (9 fields per row)
		// =========================================================
		String[] p1Fields = { "NAME_OF_BANK_AND_COUNTRY_NOSTRO", "TYPE_OF_ACCOUNT_NOSTRO", "PURPOSE_NOSTRO",
				"CURRENCY_NOSTRO", "SOVEREIGN_RATING_AAA_AA_A1_NOSTRO", "RISK_WEIGHT_NOSTRO", "AMOUNT_DEMAND_NOSTRO",
				"AMOUNT_TIME_NOSTRO", "RISK_WEIGHTED_AMOUNT_NOSTRO" };

		// R1 starts at row 10 (index 10), R101 at row 110 (index 110)
		for (int i = 1; i <= 101; i++) {
			int rowIndex = 9 + i;
			populateResubP1Row(sheet, rowIndex, record, "R" + i, p1Fields, numberStyle, textStyle);
		}
	}

