	private void populateEmailP5FromRow(Sheet sheet, int rowIndex, BrrsMNosvosP5 record, String rowPrefix,
			String[] fields, CellStyle numberStyle, CellStyle textStyle) {

		Row row = sheet.getRow(rowIndex);
		if (row == null) {
			row = sheet.createRow(rowIndex);
		}

		// Columns A-G (0-6)
		for (int i = 0; i < fields.length; i++) {
			Cell cell = row.getCell(i);
			if (cell == null) {
				cell = row.createCell(i);
			}

			String methodName = "get" + rowPrefix + "_" + fields[i];
			try {
				Method method = record.getClass().getMethod(methodName);
				Object value = method.invoke(record);

				if (value instanceof BigDecimal) {
					BigDecimal bigDecimalValue = (BigDecimal) value;
					if (bigDecimalValue != null) {
						cell.setCellValue(bigDecimalValue.doubleValue());
						cell.setCellStyle(numberStyle);
					} else {
						cell.setCellValue("");
						cell.setCellStyle(textStyle);
					}
				} else if (value instanceof String) {
					String stringValue = (String) value;
					if (stringValue != null && !stringValue.isEmpty()) {
						cell.setCellValue(stringValue.trim());
						cell.setCellStyle(textStyle);
					} else {
						cell.setCellValue("");
						cell.setCellStyle(textStyle);
					}
				} else {
					cell.setCellValue("");
					cell.setCellStyle(textStyle);
				}
			} catch (Exception e) {
				logger.error("Error populating Email P5 From row {} field {}", rowIndex, fields[i], e);
				cell.setCellValue("");
				cell.setCellStyle(textStyle);
			}
		}
	}

