	private void writeRowData1(Sheet sheet, List<BrrsMNosvosP1> dataList, String[] rowCodes, String[] fieldSuffixes,
			int baseRow, CellStyle numberStyle, CellStyle textStyle) {

		logger.info("came to write row data 1 method");

		if (dataList == null || dataList.isEmpty()) {
			logger.warn("No data available for P1");
			return;
		}

		for (BrrsMNosvosP1 record : dataList) {
			for (int rowIndex = 0; rowIndex < rowCodes.length; rowIndex++) {
				String rowCode = rowCodes[rowIndex];
				Row row = sheet.getRow(baseRow + rowIndex);
				if (row == null) {
					row = sheet.createRow(baseRow + rowIndex);
				}

				for (int colIndex = 0; colIndex < fieldSuffixes.length; colIndex++) {
					String fieldName = rowCode + "_" + fieldSuffixes[colIndex];
					int excelColIndex = 1 + colIndex; // P1 starts at Column B
					Cell cell = row.createCell(excelColIndex);

					try {
						Field field = BrrsMNosvosP1.class.getDeclaredField(fieldName);
						field.setAccessible(true);
						Object value = field.get(record);

						if (value == null) {
							cell.setCellValue("");
							cell.setCellStyle(textStyle);
							continue;
						}

						if (value instanceof BigDecimal) {
							cell.setCellValue(((BigDecimal) value).doubleValue());
							cell.setCellStyle(numberStyle);
						} else if (value instanceof String) {
							cell.setCellValue((String) value);
							cell.setCellStyle(textStyle);
						} else {
							cell.setCellValue("");
							cell.setCellStyle(textStyle);
						}
					} catch (NoSuchFieldException | IllegalAccessException e) {
						cell.setCellValue("");
						cell.setCellStyle(textStyle);
						logger.warn("Field not found or inaccessible: {}", fieldName);
					}
				}
			}
		}
	}

