	// ================================================================
	// ======================== RESUB LIST METHODS =====================
	// ================================================================

	public List<Object[]> getM_NOSVOSResub() {
		List<Object[]> resubList = new ArrayList<>();
		try {
			// P1 Resub
			List<BrrsMNosvosP1ResbuSummaryEntity> p1List = p1ResbuSummary_getdatabydateListWithVersion();
			for (BrrsMNosvosP1ResbuSummaryEntity entity : p1List) {
				resubList.add(new Object[] { entity.getREPORT_DATE(), entity.getREPORT_VERSION(),
						entity.getREPORT_RESUB_DATE() });
			}

			// P2 Resub
			List<BrrsMNosvosP2ResbuSummaryEntity> p2List = p2ResbuSummary_getdatabydateListWithVersion();
			for (BrrsMNosvosP2ResbuSummaryEntity entity : p2List) {
				resubList.add(new Object[] { entity.getREPORT_DATE(), entity.getREPORT_VERSION(),
						entity.getREPORT_RESUB_DATE() });
			}

			// P3 Resub
			List<BrrsMNosvosP3ResbuSummaryEntity> p3List = p3ResbuSummary_getdatabydateListWithVersion();
			for (BrrsMNosvosP3ResbuSummaryEntity entity : p3List) {
				resubList.add(new Object[] { entity.getREPORT_DATE(), entity.getREPORT_VERSION(),
						entity.getREPORT_RESUB_DATE() });
			}

			// P4 Resub
			List<BrrsMNosvosP4ResbuSummaryEntity> p4List = p4ResbuSummary_getdatabydateListWithVersion();
			for (BrrsMNosvosP4ResbuSummaryEntity entity : p4List) {
				resubList.add(new Object[] { entity.getREPORT_DATE(), entity.getREPORT_VERSION(),
						entity.getREPORT_RESUB_DATE() });
			}

			// P5 Resub
			List<BrrsMNosvosP5ResbuSummaryEntity> p5List = p5ResbuSummary_getdatabydateListWithVersion();
			for (BrrsMNosvosP5ResbuSummaryEntity entity : p5List) {
				resubList.add(new Object[] { entity.getREPORT_DATE(), entity.getREPORT_VERSION(),
						entity.getREPORT_RESUB_DATE() });
			}

			logger.info("Fetched {} resub record(s)", resubList.size());

		} catch (Exception e) {
			logger.error("Error fetching NOSVOS Resub data", e);
		}
		return resubList;
	}

