	// ================================================================
	// RESUB P1
	// ================================================================

	@Transactional
	public void updateReportResub(BrrsMNosvosP1ResbuSummaryEntity updatedEntity) {

		logger.info("Came to services");
		logger.info("Report Date: {}", updatedEntity.getREPORT_DATE());

		Date reportDate = updatedEntity.getREPORT_DATE();

		Optional<BrrsMNosvosP1ResbuSummaryEntity> latestArchivalOpt1 = p1ResbuSummary_getLatestArchivalVersionByDate(
				reportDate);

		int newVersion = 0;
		if (latestArchivalOpt1.isPresent()) {
			BrrsMNosvosP1ResbuSummaryEntity latestArchival = latestArchivalOpt1.get();
			try {
				newVersion = Integer.parseInt(latestArchival.getREPORT_VERSION()) + 1;
			} catch (NumberFormatException e) {
				logger.error("Invalid version format. Defaulting to version 1");
				newVersion = 1;
			}
		} else {
			logger.info("No previous archival found for date: {}", reportDate);
		}

		String version = String.valueOf(newVersion);

		BrrsMNosvosP1ResbuSummaryEntity summarySave = new BrrsMNosvosP1ResbuSummaryEntity();
		BeanUtils.copyProperties(updatedEntity, summarySave);

		Date now = new Date();
		summarySave.setREPORT_DATE(reportDate);
		summarySave.setREPORT_RESUB_DATE(now);
		summarySave.setREPORT_VERSION(version);

		// Insert into RESUB SUMMARY
		jdbcTemplate.update(
				"INSERT INTO BRRS_M_NOSVOS_P1_RESUB_SUMMARY (" + "REPORT_DATE, REPORT_VERSION, REPORT_RESUB_DATE, "
						+ "REPORT_FREQUENCY, REPORT_CODE, REPORT_DESC, " + "ENTITY_FLG, MODIFY_FLG, DEL_FLG"
						+ ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
				summarySave.getREPORT_DATE(), summarySave.getREPORT_VERSION(), summarySave.getREPORT_RESUB_DATE(),
				summarySave.getREPORT_FREQUENCY(), summarySave.getREPORT_CODE(), summarySave.getREPORT_DESC(),
				summarySave.getENTITY_FLG(), summarySave.getMODIFY_FLG(), summarySave.getDEL_FLG());

		BrrsMNosvosP1ResbuDetailEntity resubDetail = new BrrsMNosvosP1ResbuDetailEntity();
		BrrsMNosvosP1ArchivalDetail resubArchDetail = new BrrsMNosvosP1ArchivalDetail();
		BrrsMNosvosP1Archival resubArchSummary = new BrrsMNosvosP1Archival();

		BeanUtils.copyProperties(summarySave, resubDetail);
		BeanUtils.copyProperties(summarySave, resubArchSummary);
		BeanUtils.copyProperties(summarySave, resubArchDetail);

		// Insert into ARCHIVAL DETAIL
		jdbcTemplate.update(
				"INSERT INTO BRRS_M_NOSVOS_P1_ARCHIVAL_DETAIL (" + "REPORT_DATE, REPORT_VERSION, REPORT_RESUB_DATE, "
						+ "REPORT_FREQUENCY, REPORT_CODE, REPORT_DESC, " + "ENTITY_FLG, MODIFY_FLG, DEL_FLG"
						+ ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
				resubArchDetail.getREPORT_DATE(), resubArchDetail.getREPORT_VERSION(),
				resubArchDetail.getREPORT_RESUB_DATE(), resubArchDetail.getREPORT_FREQUENCY(),
				resubArchDetail.getREPORT_CODE(), resubArchDetail.getREPORT_DESC(), resubArchDetail.getENTITY_FLG(),
				resubArchDetail.getMODIFY_FLG(), resubArchDetail.getDEL_FLG());

		// Insert into ARCHIVAL SUMMARY
		jdbcTemplate.update(
				"INSERT INTO BRRS_M_NOSVOS_P1_ARCHIVAL (" + "REPORT_DATE, REPORT_VERSION, REPORT_RESUB_DATE, "
						+ "REPORT_FREQUENCY, REPORT_CODE, REPORT_DESC, " + "ENTITY_FLG, MODIFY_FLG, DEL_FLG"
						+ ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
				resubArchSummary.getREPORT_DATE(), resubArchSummary.getREPORT_VERSION(),
				resubArchSummary.getREPORT_RESUB_DATE(), resubArchSummary.getREPORT_FREQUENCY(),
				resubArchSummary.getREPORT_CODE(), resubArchSummary.getREPORT_DESC(), resubArchSummary.getENTITY_FLG(),
				resubArchSummary.getMODIFY_FLG(), resubArchSummary.getDEL_FLG());

		// Insert into RESUB DETAIL
		jdbcTemplate.update(
				"INSERT INTO BRRS_M_NOSVOS_P1_RESUB_DETAIL (" + "REPORT_DATE, REPORT_VERSION, REPORT_RESUB_DATE, "
						+ "REPORT_FREQUENCY, REPORT_CODE, REPORT_DESC, " + "ENTITY_FLG, MODIFY_FLG, DEL_FLG"
						+ ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
				resubDetail.getREPORT_DATE(), resubDetail.getREPORT_VERSION(), resubDetail.getREPORT_RESUB_DATE(),
				resubDetail.getREPORT_FREQUENCY(), resubDetail.getREPORT_CODE(), resubDetail.getREPORT_DESC(),
				resubDetail.getENTITY_FLG(), resubDetail.getMODIFY_FLG(), resubDetail.getDEL_FLG());

		logger.info("P1 Resubmission Version Created: {}", newVersion);
	}

