	// PRIMARY KEY

	public class BRRS_NOSVOS_Summary_PK implements Serializable {

		private static final long serialVersionUID = 1L;

		private Date REPORT_DATE;
		private String REPORT_VERSION;

		// default constructor
		public BRRS_NOSVOS_Summary_PK() {
		}

		// parameterized constructor
		public BRRS_NOSVOS_Summary_PK(Date REPORT_DATE, String REPORT_VERSION) {
			this.REPORT_DATE = REPORT_DATE;
			this.REPORT_VERSION = REPORT_VERSION;
		}

		// equals and hashCode
		@Override
		public boolean equals(Object o) {
			if (this == o)
				return true;
			if (!(o instanceof BRRS_NOSVOS_Summary_PK))
				return false;
			BRRS_NOSVOS_Summary_PK that = (BRRS_NOSVOS_Summary_PK) o;
			return Objects.equals(REPORT_DATE, that.REPORT_DATE) && Objects.equals(REPORT_VERSION, that.REPORT_VERSION);
		}

		@Override
		public int hashCode() {
			return Objects.hash(REPORT_DATE, REPORT_VERSION);
		}

		// getters & setters
		public Date getREPORT_DATE() {
			return REPORT_DATE;
		}

		public void setREPORT_DATE(Date REPORT_DATE) {
			this.REPORT_DATE = REPORT_DATE;
		}

		public String getREPORT_VERSION() {
			return REPORT_VERSION;
		}

		public void setREPORT_VERSION(String REPORT_VERSION) {
			this.REPORT_VERSION = REPORT_VERSION;
		}
	}

